/* GC9306 (240 x 320, the 1.5 inch Tap panel): the factory test sketch's init and
 * nothing more - sleep out 120 ms, RGB565, display on 50 ms. Its command set is
 * the ST7789's, but the ST7789 table's porch, gate and gamma settings were never
 * tried on this glass, and the vendor's own sketch runs without them. Inversion
 * and MADCTL are the panel's, sent by LB_TFT.cpp. */
static const uint8_t LB_INITSEQ_GC9306[] = {
  0x11,0x00,0x78,
  0x3A,0x01,0x00,0x55,
  0x29,0x00,0x32,
  0xFF,0xFF,
};

